def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Identify straight 5-lines; copy the adjacent colored pattern orthogonally along them.
    # Horizontal 5-line with a perpendicular colored strip at its left/right end.
    for r in range(h):
        cs=[c for c,v in enumerate(g[r]) if v==5]
        if len(cs)>=2:
            a,b=min(cs),max(cs)
            for edge,step in ((a,-1),(b,1)):
                # contiguous nonzero non-5 pattern perpendicular to line, from endpoint
                rr=r+step
                while 0<=rr<h and g[rr][edge] not in (0,5): rr+=step
                end=rr-step
                if end!=r:
                    vals=[g[x][edge] for x in range(r+step,end+step,step)]
                    for c in range(a,b+1):
                        for i,v in enumerate(vals):
                            x=r+step*(i+1)
                            if 0<=x<h:g[x][c]=v
    # Vertical line analogous: colored pattern extends sideways from either endpoint row.
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]==5]
        if len(rs)>=2:
            a,b=min(rs),max(rs)
            for edge,step in ((a,-1),(b,1)):
                # Find colored run immediately alongside line, from endpoint row.
                for dc in (-1,1):
                    x=c+dc
                    vals=[]
                    while 0<=x<w and g[edge][x] not in (0,5):
                        vals.append(g[edge][x]); x+=dc
                    if vals:
                        for r in range(a,b+1):
                            for i,v in enumerate(vals):
                                xx=c+dc*(i+1)
                                if 0<=xx<w:g[r][xx]=v
    return g
