def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Extend the colored stripe below a horizontal 5-bar across its span.
    for r in range(h):
        cols = [c for c, v in enumerate(g[r]) if v == 5]
        if len(cols) < 2:
            continue
        left, right = min(cols), max(cols)
        values = []
        rr = r + 1
        while rr < h and g[rr][left] not in (0, 5):
            values.append(g[rr][left])
            rr += 1
        for c in range(left, right + 1):
            for i, value in enumerate(values):
                if r + 1 + i < h:
                    g[r + 1 + i][c] = value

    # Repeat the colored row pattern attached to the end of a vertical 5-bar.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if len(rows) < 2:
            continue
        top, bottom = min(rows), max(rows)
        x = c + 1
        pattern = []
        while x < w and g[bottom][x] not in (0, 5):
            pattern.append(g[bottom][x])
            x += 1
        if pattern:
            for r in range(top, bottom + 1):
                for i, value in enumerate(pattern):
                    if c + 1 + i < w:
                        g[r][c + 1 + i] = value
    return g
